def main():
    root, out = sys.argv[1], sys.argv[2]
    rows = []
    for r in R:
        (rid, repo, doi, title, years, months, n, mode, pol, w, lic, com, tier, ddir, notes) = r
        downloaded = "no"
        local = ""
        if ddir and os.path.isdir(os.path.join(root, ddir)):
            man = os.path.join(root, ddir, "manifest.json")
            if os.path.exists(man):
                m = json.load(open(man))
                if any(f.get("status") == "downloaded" for f in m.get("files", [])):
                    downloaded = "yes" if not rid.startswith(("zenodo_5167557",)) else "partial (codebook only)"
                    local = os.path.join(".synthetic-lab-data/raw/political/repos", ddir)
            sp = os.path.join(root, ddir, "summary.json")
            if n is None and os.path.exists(sp):
                v = json.load(open(sp)).get("verified", {})
                ns = [x.get("n_greece") for x in v.values() if isinstance(x.get("n_greece"), int)]
                if rid in ("harvard_10.7910_DVN_KOO6MP", "harvard_10.7910_DVN_CPDFPQ"):
                    n = "; ".join(f"{k.split('/')[-1]}={x.get('n_greece')}" for k, x in v.items())
                elif rid == "harvard_10.7910_DVN_ADQPHQ":
                    n = sum(ns)
                elif ns:
                    n = max(ns)
        rows.append({"id": rid, "repository": repo, "doi_or_url": doi, "title": title, "fieldwork_years": years,
                     "fieldwork_months": months, "n_greece": "" if n is None else n, "mode_sampling": mode,
                     "political_vars": pol, "weights_var": w, "licence": lic, "commercial_use": com,
                     "access_tier": tier, "downloaded": downloaded, "local_path": local, "notes": notes})
    os.makedirs(os.path.dirname(out), exist_ok=True)
    with open(out, "w", newline="", encoding="utf-8") as fh:
        wr = csv.DictWriter(fh, fieldnames=COLS)
        wr.writeheader()
        wr.writerows(rows)
    print(len(rows), "rows;", sum(1 for r in rows if r["downloaded"].startswith("yes")), "downloaded")


if __name__ == "__main__":
    main()
